changeSet.sql:
INSERT INTO public.retail_location ( tenant_id, location_name, location_code, retailer_type_code, brand, region, address_line_1, address_line_2, city, state_province, zip_code, country, latitude, longitude, timezone, is_24_hours, is_active, included_in_subscription, created_at, updated_at ) SELECT g.tenant_id, g.station_name, g.station_code, 'GAS_STATION', g.brand, g.region, g.address_line_1, g.address_line_2, g.city, g.state_province, g.zip_code, g.country, g.latitude, g.longitude, g.timezone, g.is_24_hours, g.is_active, g.included_in_subscription, g.created_at, g.updated_at FROM public.gas_station_location g WHERE NOT EXISTS ( SELECT 1 FROM public.retail_location existing WHERE existing.tenant_id = g.tenant_id AND existing.location_code = g.station_code );
INSERT INTO public.retail_location_profile ( tenant_id, location_id, fuel_dispenser_count, has_car_wash, has_lottery, has_foodservice, created_at, updated_at ) SELECT g.tenant_id, store.id, g.fuel_dispenser_count, g.has_car_wash, g.has_lottery, g.has_foodservice, g.created_at, g.updated_at FROM public.gas_station_location g JOIN public.retail_location store ON store.tenant_id = g.tenant_id AND store.location_code = g.station_code WHERE ( g.fuel_dispenser_count IS NOT NULL OR g.has_car_wash OR g.has_lottery OR g.has_foodservice ) AND NOT EXISTS ( SELECT 1 FROM public.retail_location_profile existing WHERE existing.location_id = store.id );
INSERT INTO public.retail_integration ( tenant_id, location_id, system_type, provider_name, connection_mode, config_json, credentials_ref, sync_frequency, last_sync_at, last_sync_status, is_enabled, created_at, updated_at ) SELECT link.tenant_id, store.id, link.system_type, link.provider_name, link.connection_mode, link.config_json, link.credentials_ref, link.sync_frequency, link.last_sync_at, link.last_sync_status, link.is_enabled, link.created_at, link.updated_at FROM public.gas_station_integration link JOIN public.gas_station_location g ON g.id = link.station_id JOIN public.retail_location store ON store.tenant_id = g.tenant_id AND store.location_code = g.station_code WHERE NOT EXISTS ( SELECT 1 FROM public.retail_integration existing WHERE existing.location_id = store.id AND existing.system_type = link.system_type AND existing.provider_name IS NOT DISTINCT FROM link.provider_name );
INSERT INTO public.retail_daily_metrics ( tenant_id, location_id, metric_date, sales_usd, transactions_count, labor_hours, labor_cost_usd, waste_cost_usd, shrink_cost_usd, expected_profit_usd, actual_profit_usd, metrics_json, source_model_run_id, created_at, updated_at ) SELECT day.tenant_id, store.id, day.metric_date, CASE WHEN day.in_store_sales_usd IS NULL AND day.foodservice_sales_usd IS NULL AND day.lottery_sales_usd IS NULL THEN NULL ELSE COALESCE(day.in_store_sales_usd, 0) + COALESCE(day.foodservice_sales_usd, 0) + COALESCE(day.lottery_sales_usd, 0) END, day.transactions_count, day.labor_hours, day.labor_cost_usd, day.waste_cost_usd, day.shrink_cost_usd, day.expected_profit_usd, day.actual_profit_usd, day.metrics_json, day.source_model_run_id, day.created_at, day.updated_at FROM public.gas_station_daily_metrics day JOIN public.gas_station_location g ON g.id = day.station_id JOIN public.retail_location store ON store.tenant_id = g.tenant_id AND store.location_code = g.station_code WHERE NOT EXISTS ( SELECT 1 FROM public.retail_daily_metrics existing WHERE existing.location_id = store.id AND existing.metric_date = day.metric_date );
INSERT INTO public.retail_fuel_day ( tenant_id, location_id, metric_date, fuel_gallons_sold, fuel_revenue_usd, fuel_margin_cents_per_gallon, created_at, updated_at ) SELECT day.tenant_id, store.id, day.metric_date, day.fuel_gallons_sold, day.fuel_revenue_usd, day.fuel_margin_cents_per_gallon, day.created_at, day.updated_at FROM public.gas_station_daily_metrics day JOIN public.gas_station_location g ON g.id = day.station_id JOIN public.retail_location store ON store.tenant_id = g.tenant_id AND store.location_code = g.station_code WHERE ( day.fuel_gallons_sold IS NOT NULL OR day.fuel_revenue_usd IS NOT NULL OR day.fuel_margin_cents_per_gallon IS NOT NULL ) AND NOT EXISTS ( SELECT 1 FROM public.retail_fuel_day existing WHERE existing.location_id = store.id AND existing.metric_date = day.metric_date );
INSERT INTO public.retail_department_day ( tenant_id, location_id, metric_date, department, sales_usd, created_at, updated_at ) SELECT day.tenant_id, store.id, day.metric_date, split.department, split.sales_usd, day.created_at, day.updated_at FROM public.gas_station_daily_metrics day JOIN public.gas_station_location g ON g.id = day.station_id JOIN public.retail_location store ON store.tenant_id = g.tenant_id AND store.location_code = g.station_code JOIN ( SELECT id, 'IN_STORE'::varchar(32) AS department, in_store_sales_usd AS sales_usd FROM public.gas_station_daily_metrics WHERE in_store_sales_usd IS NOT NULL AND in_store_sales_usd <> 0 UNION ALL SELECT id, 'FOODSERVICE'::varchar(32), foodservice_sales_usd FROM public.gas_station_daily_metrics WHERE foodservice_sales_usd IS NOT NULL AND foodservice_sales_usd <> 0 UNION ALL SELECT id, 'LOTTERY'::varchar(32), lottery_sales_usd FROM public.gas_station_daily_metrics WHERE lottery_sales_usd IS NOT NULL AND lottery_sales_usd <> 0 ) split ON split.id = day.id WHERE NOT EXISTS ( SELECT 1 FROM public.retail_department_day existing WHERE existing.location_id = store.id AND existing.metric_date = day.metric_date AND existing.department = split.department );
INSERT INTO public.retail_recommendation ( tenant_id, location_id, recommendation_date, category, title, detail, estimated_impact_usd, priority, confidence_pct, explanation, status, owner_feedback, source_model_run_id, created_at, updated_at ) SELECT card.tenant_id, store.id, card.recommendation_date, card.category, card.title, card.detail, card.estimated_impact_usd, card.priority, card.confidence_pct, card.explanation, card.status, card.owner_feedback, card.source_model_run_id, card.created_at, card.updated_at FROM public.gas_station_recommendation card JOIN public.gas_station_location g ON g.id = card.station_id JOIN public.retail_location store ON store.tenant_id = g.tenant_id AND store.location_code = g.station_code WHERE card.station_id IS NOT NULL AND NOT EXISTS ( SELECT 1 FROM public.retail_recommendation existing WHERE existing.tenant_id = card.tenant_id AND existing.location_id = store.id AND existing.recommendation_date = card.recommendation_date AND existing.category = card.category AND existing.title = card.title );
INSERT INTO public.retail_recommendation ( tenant_id, location_id, recommendation_date, category, title, detail, estimated_impact_usd, priority, confidence_pct, explanation, status, owner_feedback, source_model_run_id, created_at, updated_at ) SELECT card.tenant_id, NULL, card.recommendation_date, card.category, card.title, card.detail, card.estimated_impact_usd, card.priority, card.confidence_pct, card.explanation, card.status, card.owner_feedback, card.source_model_run_id, card.created_at, card.updated_at FROM public.gas_station_recommendation card WHERE card.station_id IS NULL AND NOT EXISTS ( SELECT 1 FROM public.retail_recommendation existing WHERE existing.tenant_id = card.tenant_id AND existing.location_id IS NULL AND existing.recommendation_date = card.recommendation_date AND existing.category = card.category AND existing.title = card.title );
INSERT INTO public.retail_user_location_assignment ( tenant_id, user_profile_id, location_id, assigned_by_user_profile_id, notes, created_at, updated_at ) SELECT assignment.tenant_id, assignment.user_profile_id, store.id, assignment.assigned_by_user_profile_id, assignment.notes, assignment.created_at, assignment.updated_at FROM public.gas_station_user_station_assignment assignment JOIN public.gas_station_location g ON g.id = assignment.station_id JOIN public.retail_location store ON store.tenant_id = g.tenant_id AND store.location_code = g.station_code WHERE NOT EXISTS ( SELECT 1 FROM public.retail_user_location_assignment existing WHERE existing.tenant_id = assignment.tenant_id AND existing.user_profile_id = assignment.user_profile_id AND existing.location_id = store.id );
DROP TABLE IF EXISTS public.gas_station_recommendation CASCADE; DROP TABLE IF EXISTS public.gas_station_daily_metrics CASCADE; DROP TABLE IF EXISTS public.gas_station_integration CASCADE; DROP TABLE IF EXISTS public.gas_station_user_station_assignment CASCADE; DROP TABLE IF EXISTS public.gas_station_location CASCADE; DROP SEQUENCE IF EXISTS public.gas_station_recommendation_id_seq; DROP SEQUENCE IF EXISTS public.gas_station_daily_metrics_id_seq; DROP SEQUENCE IF EXISTS public.gas_station_integration_id_seq; DROP SEQUENCE IF EXISTS public.gas_station_user_station_assignment_id_seq; DROP SEQUENCE IF EXISTS public.gas_station_location_id_seq;
